def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    value = new - old
    return {
        "value": value,
        "trace": {
            "old_hqla": old,
            "new_hqla": new,
            "difference": value,
            "output_meta": {
                "currency": "USD",
                "scale": "billion",
                "unit": None
            }
        }
    }
